using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1. GetTypeInfo<T>() — returns a strongly-typed JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialized with typed metadata: {json}");

// 2. TryGetTypeInfo<T>() — probe without throwing
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
{
    Console.WriteLine($"TryGet succeeded for {info!.Type.Name}");
}

// Demonstrate a resolver that only knows about Person (not about int[])
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
        .WithAddedModifier(ti =>
        {
            // allow everything through — resolver itself is what limits types
        })
};
// Freeze so TryGetTypeInfo can be called
limited.MakeReadOnly(populateMissingResolver: false);

// Source-generated or custom resolvers may not resolve every type.
// Simulate by using a resolver that wraps and filters:
var selective = new JsonSerializerOptions
{
    TypeInfoResolver = new FilteredResolver(typeof(Person))
};
selective.MakeReadOnly(populateMissingResolver: false);

if (selective.TryGetTypeInfo<int[]>(out _))
    Console.WriteLine("int[] metadata found (unexpected)");
else
    Console.WriteLine("TryGet correctly reports int[] metadata not available");

public record Person(string Name, int Age);

/// <summary>A resolver that only exposes metadata for a fixed set of types.</summary>
file class FilteredResolver : IJsonTypeInfoResolver
{
    private readonly HashSet<Type> _allowed;
    private readonly DefaultJsonTypeInfoResolver _inner = new();
    public FilteredResolver(params Type[] allowed) => _allowed = new(allowed);
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
        => _allowed.Contains(type) ? _inner.GetTypeInfo(type, options) : null;
}

