using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1. GetTypeInfo<T>() — returns a strongly-typed JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialized with typed metadata: {json}");

// 2. TryGetTypeInfo<T>() — probe without throwing
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
{
    Console.WriteLine($"TryGet succeeded for {info!.Type.Name}");
}

// Demonstrate TryGetTypeInfo returning false when a type isn't resolvable.
// Use a custom resolver that only exposes metadata for Person.
var selective = new JsonSerializerOptions
{
    TypeInfoResolver = new FilteredResolver(typeof(Person))
};
selective.MakeReadOnly(populateMissingResolver: false);

if (selective.TryGetTypeInfo<int[]>(out _))
    Console.WriteLine("int[] metadata found (unexpected)");
else
    Console.WriteLine("TryGet correctly reports int[] metadata is not available");

public record Person(string Name, int Age);

